#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Configuration
const MIGRATIONS_DIR = './migrations';

function readMigrations() {
    try {
        // Check if migrations directory exists
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.log(`Migrations directory '${MIGRATIONS_DIR}' not found.`);
            console.log('Would create directory and apply no migrations.');
            return [];
        }

        // Read all files from migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for SQL files and sort them
        const sqlFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort((a, b) => a.localeCompare(b));

        if (sqlFiles.length === 0) {
            console.log('No SQL files found in migrations directory.');
            return [];
        }

        return sqlFiles;
    } catch (error) {
        console.error('Error reading migrations directory:', error.message);
        process.exit(1);
    }
}

function logMigrations(migrations) {
    console.log('\n=== Database Migration Script ===\n');
    console.log(`Reading migrations from: ${MIGRATIONS_DIR}`);

    if (migrations.length === 0) {
        console.log('No migrations to apply.');
        return;
    }

    console.log(`\nFound ${migrations.length} migration(s) to apply:\n`);

    migrations.forEach((filename, index) => {
        console.log(`${index + 1}. ${filename}`);
    });

    console.log('\n=== Migration simulation complete ===');
    console.log('NOTE: This script only logs what would be applied.');
    console.log('To actually execute migrations, you would:');
    console.log('1. Read each SQL file');
    console.log('2. Execute the SQL against your database');
    console.log('3. Track which migrations have been applied');
}

// Main execution
const migrations = readMigrations();
logMigrations(migrations);

// Export for testing purposes
module.exports = { readMigrations, logMigrations };

-- Create users table
CREATE TABLE users (
    id SERIAL PRIMARY KEY,
    username VARCHAR(50) UNIQUE NOT NULL,
    email VARCHAR(100) UNIQUE NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Create index on username
CREATE INDEX idx_users_username ON users(username);

-- Create index on email
CREATE INDEX idx_users_email ON users(email);

-- Create posts table
CREATE TABLE posts (
    id SERIAL PRIMARY KEY,
    user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,
    title VARCHAR(200) NOT NULL,
    content TEXT NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Create index on user_id for faster queries
CREATE INDEX idx_posts_user_id ON posts(user_id);

-- Create index on created_at for sorting
CREATE INDEX idx_posts_created_at ON posts(created_at);

-- Create comments table
CREATE TABLE comments (
    id SERIAL PRIMARY KEY,
    post_id INTEGER REFERENCES posts(id) ON DELETE CASCADE,
    user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,
    content TEXT NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Create index on post_id for faster comment retrieval
CREATE INDEX idx_comments_post_id ON comments(post_id);

-- Create index on user_id
CREATE INDEX idx_comments_user_id ON comments(user_id);

-- Add foreign key constraint
ALTER TABLE comments ADD CONSTRAINT fk_comments_post FOREIGN KEY (post_id) REFERENCES posts(id);
ALTER TABLE comments ADD CONSTRAINT fk_comments_user FOREIGN KEY (user_id) REFERENCES users(id);

