            }
        }

        return envVars;
    } catch (error) {
        console.error('Error reading environment file:', error.message);
        return null;
    }
}

function readDatabaseUrl(envVars) {
    return envVars ? envVars.DATABASE_URL || null : null;
}

function logDatabaseConnection(databaseUrl) {
