const fs = require('fs');
const path = require('path');

// Configuration
const migrationsDir = './migrations/';

function getMigrationFiles() {
    try {
        // Check if migrations directory exists
        if (!fs.existsSync(migrationsDir)) {
            console.log('Migrations directory not found. Creating empty directory...');
            fs.mkdirSync(migrationsDir, { recursive: true });
            return [];
        }

        // Read all files from migrations directory
        const files = fs.readdirSync(migrationsDir);

        // Filter for SQL files and sort them
        const sqlFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort((a, b) => {
                // Extract version numbers from filenames (assuming format like 001_initial.sql)
                const versionA = parseInt(a.split('_')[0]);
                const versionB = parseInt(b.split('_')[0]);

                if (!isNaN(versionA) && !isNaN(versionB)) {
                    return versionA - versionB;
                }

                // Fallback to alphabetical sort if no version numbers
                return a.localeCompare(b);
            });

        return sqlFiles;
    } catch (error) {
        console.error('Error reading migrations directory:', error.message);
        return [];
    }
}

function logMigrationFiles() {
    console.log('=== Database Migration Script ===');
    console.log(`Reading migrations from: ${path.resolve(migrationsDir)}`);
    console.log('');

    const migrationFiles = getMigrationFiles();

    if (migrationFiles.length === 0) {
        console.log('No migration files found.');
        console.log('To create a migration, add SQL files to the migrations/ directory.');
        console.log('Recommended naming convention: 001_initial.sql, 002_add_users.sql, etc.');
        return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):`);
    console.log('');

    migrationFiles.forEach((file, index) => {
        const filePath = path.join(migrationsDir, file);
        console.log(`${index + 1}. ${file}`);

        // Optional: Log the first few lines of each SQL file for context
        try {
            const content = fs.readFileSync(filePath, 'utf8');
            const firstLines = content.split('\n').slice(0, 3).join('\n');
            if (firstLines.trim()) {
                console.log(`   Preview: ${firstLines.substring(0, 60)}${firstLines.length > 60 ? '...' : ''}`);
            }
        } catch (error) {
            console.log(`   Error reading file: ${error.message}`);
        }
        console.log('');
    });

    console.log('Migration files would be applied in the order shown above.');
    console.log('To actually apply these migrations, you would:');
    console.log('1. Connect to your database');
    console.log('2. Read each file and execute the SQL');
    console.log('3. Track which migrations have been applied');
}

// Handle command line arguments
if (require.main === module) {
    if (process.argv.includes('--help') || process.argv.includes('-h')) {
        console.log('Usage: node migrate.js [--dry-run]');
        console.log('');
        console.log('Options:');
        console.log('  --dry-run     Show what would be applied without executing (default)');
        console.log('  --help, -h    Show this help message');
        process.exit(0);
    }

    logMigrationFiles();
}

module.exports = {
    getMigrationFiles,
    logMigrationFiles
};

