    const sanitized = {...envVars};

    // Sanitize sensitive data for safe logging
    if (sanitized.DATABASE_URL) {
        // Mask password in database URL
        sanitized.DATABASE_URL = sanitized.DATABASE_URL.replace(
            /:\/\/([^:]+):([^@]+)@/,
            '://$1:***@'
        );
    }

    // Remove other potentially sensitive values
    const sensitiveKeys = ['PASSWORD', 'SECRET', 'KEY', 'TOKEN'];
    Object.keys(sanitized).forEach(key => {
        sensitiveKeys.forEach(sensitive => {
            if (key.toUpperCase().includes(sensitive)) {
                sanitized[key] = '***REDACTED***';
            }
        });
    });

    return sanitized;
}

