const fs = require('fs');
const path = require('path');

function readMigrations(migrationsDir) {
    try {
        // Read all files in the migrations directory
        const files = fs.readdirSync(migrationsDir);

        // Filter for SQL files and sort them numerically/chronologically
        const migrationFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort((a, b) => {
                // Extract numbers from filenames for sorting (e.g., 001_initial.sql -> 1)
                const getNumber = (filename) => {
                    const match = filename.match(/^(\d+)/);
                    return match ? parseInt(match[1]) : 0;
                };
                return getNumber(a) - getNumber(b);
            });

        return migrationFiles;
    } catch (error) {
        if (error.code === 'ENOENT') {
            console.error(`Error: Migrations directory '${migrationsDir}' not found.`);
            process.exit(1);
        }
        throw error;
    }
}

function logMigrations(migrationsDir, migrationFiles) {
    console.log('Migrations to apply (in order):');
    console.log('================================');

    if (migrationFiles.length === 0) {
        console.log('No migration files found.');
        return;
    }

    migrationFiles.forEach((file, index) => {
        const fullPath = path.join(migrationsDir, file);
        console.log(`${index + 1}. ${file}`);

        // Optional: Log the content of each migration file
        try {
            const content = fs.readFileSync(fullPath, 'utf8');
            console.log(`   Preview: ${content.substring(0, 100).replace(/\n/g, ' ').trim()}${content.length > 100 ? '...' : ''}`);
        } catch (error) {
            console.log(`   Error reading file: ${error.message}`);
        }

        console.log(''); // Empty line for readability
    });
}

// Main execution
function main() {
    const migrationsDir = './migrations/';

    console.log('Database Migration Script');
    console.log('=========================');
    console.log(`Reading migrations from: ${migrationsDir}\n`);

    const migrationFiles = readMigrations(migrationsDir);
    logMigrations(migrationsDir, migrationFiles);

    console.log(`Total migrations found: ${migrationFiles.length}`);
}

// Run the script
if (require.main === module) {
    main();
}

module.exports = {
    readMigrations,
    logMigrations
};

