function parseEnvFile(filePath) {
    const envVars = {};

    try {
        if (fs.existsSync(filePath)) {
            const content = fs.readFileSync(filePath, 'utf8');
            const lines = content.split('\n');

            for (const line of lines) {
                const trimmedLine = line.trim();
                // Skip empty lines and comments
                if (!trimmedLine || trimmedLine.startsWith('#')) {
                    continue;
                }

                const equalsIndex = trimmedLine.indexOf('=');
                if (equalsIndex !== -1) {
                    const key = trimmedLine.substring(0, equalsIndex).trim();
                    const value = trimmedLine.substring(equalsIndex + 1).trim();
                    // Remove quotes if present
                    envVars[key] = value.replace(/^['"]|['"]$/g, '');
                }
            }
        }
    } catch (error) {
        console.warn(`Warning: Could not read .env file: ${error.message}`);
    }

    return envVars;
}

/**
 * Mask sensitive information for secure logging
 * @param {string} value - Value to mask
 * @param {string} key - Key name (for context)
 * @returns {string} Masked value
 */
function maskSensitiveValue(value, key = '') {
    if (!value) return '***';

    // Mask credentials in URLs
    if (value.includes('://') && value.includes('@')) {
        try {
            const url = new URL(value);
            if (url.username || url.password) {
                return value.replace(/\/\/[^:]*:[^@]*@/, '//***:***@');
            }
        } catch (error) {
            // If URL parsing fails, use simple masking
            return value.replace(/:[^@]*@/, ':***@');
        }
    }

    // Mask potential passwords and secrets
    const sensitiveKeys = ['pass', 'secret', 'key', 'token', 'auth'];
    if (sensitiveKeys.some(sk => key.toLowerCase().includes(sk))) {
        return '***';
    }

    return value;
