#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Configuration
const MIGRATIONS_DIR = './migrations';

/**
 * Reads SQL files from the migrations directory and returns them sorted
 * @returns {Array} Array of migration file objects with name and path
 */
function getMigrationFiles() {
    try {
        // Check if migrations directory exists
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.log(`Migrations directory '${MIGRATIONS_DIR}' not found. Creating it.`);
            fs.mkdirSync(MIGRATIONS_DIR, { recursive: true });
            return [];
        }

        // Read all files in the migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for SQL files and sort them
        const sqlFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort() // Alphabetical order (timestamps or sequential numbers work well)
            .map(file => ({
                name: file,
                path: path.join(MIGRATIONS_DIR, file)
            }));

        return sqlFiles;
    } catch (error) {
        console.error('Error reading migrations directory:', error.message);
        return [];
    }
}

/**
 * Logs the migration files that would be applied
 */
function logMigrations() {
    console.log('📋 Database Migration Script');
    console.log('='.repeat(40));

    const migrationFiles = getMigrationFiles();

    if (migrationFiles.length === 0) {
        console.log('No migration files found in ./migrations/ directory.');
        console.log('Place your SQL migration files in the migrations directory with .sql extension.');
        return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):\n`);

    // Log each migration file in order
    migrationFiles.forEach((file, index) => {
        console.log(`${index + 1}. ${file.name}`);

        // Optional: Log the first few lines of each SQL file
        try {
            const content = fs.readFileSync(file.path, 'utf8');
            const firstLine = content.split('\n')[0].trim();
            if (firstLine) {
                console.log(`   ${firstLine.slice(0, 60)}${firstLine.length > 60 ? '...' : ''}`);
            }
        } catch (error) {
            console.log(`   [Could not read file: ${error.message}]`);
        }
        console.log();
    });

    console.log('='.repeat(40));
    console.log('This is a dry run. No actual database changes were made.');
    console.log('To actually apply migrations, you would:');
    console.log('1. Connect to your database');
    console.log('2. Execute each SQL file in order');
    console.log('3. Track which migrations have been applied');
}

// Execute the script
logMigrations();

