#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Configuration
const MIGRATIONS_DIR = './migrations';

function getMigrationFiles() {
    try {
        // Read the migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for SQL files and sort them
        const sqlFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort((a, b) => {
                // Extract numeric prefixes for proper ordering
                const numA = parseInt(a.split('_')[0]) || 0;
                const numB = parseInt(b.split('_')[0]) || 0;
                return numA - numB;
            });

        return sqlFiles;
    } catch (error) {
        if (error.code === 'ENOENT') {
            console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' not found`);
        } else {
            console.error('Error reading migrations directory:', error.message);
        }
        process.exit(1);
    }
}

function logMigrations(migrations) {
    console.log('\n=== Database Migration Script ===');
    console.log(`Migrations directory: ${MIGRATIONS_DIR}`);
    console.log(`Found ${migrations.length} migration file(s):\n`);

    if (migrations.length === 0) {
        console.log('No migration files found.');
        return;
    }

    // Log each migration file in order
    migrations.forEach((filename, index) => {
        const migrationPath = path.join(MIGRATIONS_DIR, filename);
        const fileContent = fs.readFileSync(migrationPath, 'utf8');

        console.log(`${index + 1}. ${filename}`);
        console.log(`   Path: ${migrationPath}`);
        console.log(`   Size: ${fileContent.length} characters`);
        console.log(`   First line: ${fileContent.split('\n')[0].substring(0, 50)}${fileContent.split('\n')[0].length > 50 ? '...' : ''}`);
        console.log('');
    });

    console.log('=== End of Migration List ===');
}

function main() {
    console.log('Starting migration script...');

    const migrationFiles = getMigrationFiles();
    logMigrations(migrationFiles);

    console.log('\nNote: This script only lists migrations. Actual database application');
    console.log('would require database connection logic to execute the SQL files.');
}

// Run the migration script
main();

