const fs = require('fs');
const path = require('path');

// Supported SQL file extensions
const SQL_EXTENSIONS = ['.sql', '.SQL'];

// Function to read all environment variables from .env.test
function readEnvFile(envFile = '.env.test') {
    if (!fs.existsSync(envFile)) {
        console.log(`Environment file not found: ${envFile}`);
        return {};
    }

    try {
        const envContent = fs.readFileSync(envFile, 'utf8');
        const lines = envContent.split('\n');
        const envVars = {};

        for (const line of lines) {
            const trimmedLine = line.trim();
            // Skip comments and empty lines
            if (!trimmedLine || trimmedLine.startsWith('#')) continue;

            const equalsIndex = trimmedLine.indexOf('=');
            if (equalsIndex !== -1) {
                const key = trimmedLine.substring(0, equalsIndex).trim();
                let value = trimmedLine.substring(equalsIndex + 1).trim();

                // Remove quotes if present
                value = value.replace(/^['"]|['"]$/g, '');
                envVars[key] = value;
            }
        }

        return envVars;

    } catch (error) {
        console.error(`Error reading ${envFile}:`, error.message);
        return {};
    }
}

// Function to read migration files and log them in order
function readMigrations(migrationsDir = './migrations/') {

    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
        console.log('Migrations directory not found:', migrationsDir);
        return;
    }

    try {
        // Read all files in the migrations directory
        const files = fs.readdirSync(migrationsDir);

        // Filter for SQL files and sort them
        const sqlFiles = files
            .filter(file => SQL_EXTENSIONS.some(ext => file.endsWith(ext)))
            .sort((a, b) => a.localeCompare(b, undefined, {numeric: true, sensitivity: 'base'}));

        if (sqlFiles.length === 0) {
            console.log('No SQL migration files found in:', migrationsDir);
            return;
        }

        console.log('Migration files to apply (in order):');
