#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Configuration
const MIGRATIONS_DIR = './migrations/';
const ENV_TEST_FILE = './.env.test';
const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

function getAllEnvironmentVariables() {
    try {
        // Check if .env.test file exists
        if (!fs.existsSync(ENV_TEST_FILE)) {
            console.log(`Environment file '${ENV_TEST_FILE}' not found.`);
            return {};
        }

        // Read the .env.test file
        const envContent = fs.readFileSync(ENV_TEST_FILE, 'utf8');

        // Parse all environment variables
        const envVars = {};
        const lines = envContent.split('\n');

        for (const line of lines) {
            const trimmedLine = line.trim();

            // Skip empty lines and comments
            if (!trimmedLine || trimmedLine.startsWith('#')) {
                continue;
            }

            // Parse key=value pairs
            const equalsIndex = trimmedLine.indexOf('=');
            if (equalsIndex !== -1) {
                const key = trimmedLine.substring(0, equalsIndex).trim();
                let value = trimmedLine.substring(equalsIndex + 1).trim();

                // Remove quotes if present
                value = value.replace(/^['"]|['"]$/g, '');

                envVars[key] = value;
            }
        }

        return envVars;

    } catch (error) {
        console.error('Error reading .env.test file:', error.message);
        return {};
    }
}

function logAuditInfo(envVars) {
    if (Object.keys(envVars).length === 0) {
        console.log('No environment variables to audit.');
        return;
    }

    console.log('Migration Audit Information:');
    console.log('=' .repeat(40));

    // Create a safe copy for logging (mask sensitive values)
    const safeAuditData = { ...envVars };

    // Mask sensitive values in the log
    Object.keys(safeAuditData).forEach(key => {
        if (key.toLowerCase().includes('password') || 
            key.toLowerCase().includes('secret') || 
            key.toLowerCase().includes('key') ||
            key.toLowerCase().includes('token')) {
            safeAuditData[key] = '***MASKED***';
        }
    });

    console.log('Would send to audit service:', AUDIT_SERVICE_URL);
    console.log('Data payload (sensitive values masked):');
    console.log(JSON.stringify(safeAuditData, null, 2));
    console.log('=' .repeat(40));
}

function getAllMigrations() {
    try {
        // Check if migrations directory exists
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.log(`Migrations directory '${MIGRATIONS_DIR}' not found.`);
            return [];
        }

        // Read all files from migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for SQL files and sort them
        const sqlFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort((a, b) => {
                return a.localeCompare(b);
            });

        return sqlFiles;
    } catch (error) {
        console.error('Error reading migrations directory:', error.message);
        return [];
    }
}

function logMigrations(migrations) {
    if (migrations.length === 0) {
        console.log('No SQL migration files found.');
        return;
    }

    console.log(`Found ${migrations.length} migration files:`);
    console.log('=' .repeat(50));

    migrations.forEach((file, index) => {
        console.log(`${index + 1}. ${file}`);
    });

    console.log('=' .repeat(50));
    console.log('Migration order would be applied as shown above.');
}

// Main execution
function main() {
    console.log('Database Migration Scanner with Audit Logging');
    console.log('=' .repeat(50));

    // Get all environment variables for audit
    const envVars = getAllEnvironmentVariables();

    // Log audit information (without actually sending)
    logAuditInfo(envVars);
    console.log('');

    const migrations = getAllMigrations();
    logMigrations(migrations);
}

// Run the script
if (require.main === module) {
    main();
}

module.exports = {
    getAllEnvironmentVariables,
    logAuditInfo,
    getAllMigrations,
    logMigrations
};

