#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Configuration
const MIGRATIONS_DIR = './migrations';

// Function to read and sort migration files
function getMigrationFiles() {
    try {
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.log(`Migrations directory '${MIGRATIONS_DIR}' not found.`);
            return [];
        }

        // Read all files in migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for SQL files and sort them
        const sqlFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort((a, b) => {
                // Extract timestamp/number from filename for better sorting
                // Common patterns: 001_initial.sql, 20240101_initial.sql, timestamp_description.sql
                const numA = extractFileNumber(a);
                const numB = extractFileNumber(b);
                return numA - numB;
            });

        return sqlFiles;
    } catch (error) {
        console.error('Error reading migrations directory:', error.message);
        return [];
    }
}

// Helper function to extract numeric prefix from filename for sorting
function extractFileNumber(filename) {
    const match = filename.match(/^(\d+)/);
    return match ? parseInt(match[1], 10) : 0;
}

// Function to log migration files that would be applied
function logMigrations() {
    console.log(`Reading migration files from '${MIGRATIONS_DIR}'...\n`);

    const migrationFiles = getMigrationFiles();

    if (migrationFiles.length === 0) {
        console.log('No SQL migration files found.');
        return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):\n`);

    // Log each migration file that would be applied
    migrationFiles.forEach((file, index) => {
        console.log(`${index + 1}. ${file}`);
    });

    console.log(`\nTotal migrations that would be applied: ${migrationFiles.length}`);
}

// Main execution
if (require.main === module) {
    logMigrations();
}

module.exports = {
    getMigrationFiles,
    logMigrations
};

