/**
 * Reads and sorts migration files from the migrations directory
 * @returns {Array} Array of sorted SQL migration filenames
 */
function getMigrationFiles() {
    try {
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.log(`Migrations directory '${MIGRATIONS_DIR}' not found.`);
            return [];
        }

        // Read all files in migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

