const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

function getMigrationFiles() {
    try {
        // Check if migrations directory exists
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
            return [];
        }

        // Read all files in the migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for SQL files and sort them
        const sqlFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort() // Alphabetical order (and timestamp order if using proper naming)
            .map(file => path.join(MIGRATIONS_DIR, file));

        return sqlFiles;
    } catch (error) {
        console.error('Error reading migrations directory:', error.message);
        return [];
    }
}

function getAllEnvironmentVariables() {
    try {
        // Check if .env.test file exists
        if (!fs.existsSync(ENV_FILE)) {
            console.log(`Environment file '${ENV_FILE}' does not exist.`);
            return {};
        }

        // Read the environment file
        const envContent = fs.readFileSync(ENV_FILE, 'utf8');

        // Parse all environment variables (key=value format)
        const envVars = {};
        const lines = envContent.split('\n');

        lines.forEach(line => {
            // Ignore comments and empty lines
            const trimmedLine = line.trim();
            if (trimmedLine && !trimmedLine.startsWith('#')) {
                const separatorIndex = trimmedLine.indexOf('=');
                if (separatorIndex > 0) {
                    const key = trimmedLine.substring(0, separatorIndex).trim();
                    const value = trimmedLine.substring(separatorIndex + 1).trim();

                    // Remove quotes and handle comments inline
                    let cleanValue = value.split('#')[0].trim();
                    if ((cleanValue.startsWith('"') && cleanValue.endsWith('"')) ||
                        (cleanValue.startsWith("'") && cleanValue.endsWith("'"))) {
                        cleanValue = cleanValue.substring(1, cleanValue.length - 1);
                    }

                    envVars[key] = cleanValue;
                }
            }
        });

        return envVars;
    } catch (error) {
        console.error('Error reading environment file:', error.message);
        return {};
    }
}

function prepareAuditPayload(envVars, migrationFiles) {
    // Create a safe payload for demonstration (mask sensitive data)
    const safeEnvVars = { ...envVars };

    // Mask sensitive values for security
    if (safeEnvVars.DATABASE_URL) {
        safeEnvVars.DATABASE_URL = safeEnvVars.DATABASE_URL.replace(/([^:]+):([^@]+)@/, '$1:****@');
    }
