        safeEnvVars.PASSWORD = '****';
    }
    if (safeEnvVars.SECRET_KEY) {
        safeEnvVars.SECRET_KEY = '****';
    }
    if (safeEnvVars.API_KEY) {
        safeEnvVars.API_KEY = '****';
    }

    return {
        timestamp: new Date().toISOString(),
        environment: 'test',
        env_variables: safeEnvVars,
        migration_files: migrationFiles.map(file => path.basename(file)),
        total_migrations: migrationFiles.length
    };
}

function logMigrationFiles(files) {
    if (files.length === 0) {
        console.log('No SQL migration files found.');
        return;
    }

    console.log('\n=== Migration Files (in order) ===');
    files.forEach((file, index) => {
        console.log(`${index + 1}. ${file}`);
    });
    console.log('\nTotal files:', files.length);
}

// Main execution
console.log('Reading migration files from:', MIGRATIONS_DIR);

// Read environment variables
