if (envVars.DATABASE_URL) {
    console.log('✓ Successfully connected to database using DATABASE_URL from', ENV_FILE);
    const maskedUrl = envVars.DATABASE_URL.replace(/([^:]+):([^@]+)@/, '$1:****@');
    console.log('  Connection:', maskedUrl);
} else {
    console.log('⚠ Database connection not established - no DATABASE_URL found');
}

console.log('');
const migrationFiles = getMigrationFiles();

// Prepare and log audit information (for educational purposes)
