const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

class MigrationRunner {
  constructor() {
    this.migrationsDir = path.join(__dirname, 'migrations');
  }

  /**
   * Get all migration files from the migrations directory
   * @returns {Array} Array of migration file objects with name, path, and timestamp
   */
  getMigrationFiles() {
    try {
      // Check if migrations directory exists
      if (!fs.existsSync(this.migrationsDir)) {
        console.log('No migrations directory found. Creating empty directory...');
        fs.mkdirSync(this.migrationsDir, { recursive: true });
        return [];
      }

      // Read all files from migrations directory
      const files = fs.readdirSync(this.migrationsDir);

      // Filter for SQL files and parse timestamps
      const migrationFiles = files
        .filter(file => file.endsWith('.sql'))
        .map(file => {
          const filePath = path.join(this.migrationsDir, file);
          const stats = fs.statSync(filePath);

          // Extract timestamp from filename (common format: YYYYMMDDHHMMSS_filename.sql)
          const timestampMatch = file.match(/^(\d+)_/);
          const timestamp = timestampMatch ? parseInt(timestampMatch[1]) : null;

          return {
            name: file,
            path: filePath,
            timestamp: timestamp,
            createdAt: stats.birthtime
          };
        })
        .filter(migration => migration.timestamp !== null); // Only include properly formatted migrations

      // Sort migrations by timestamp (ascending order)
      return migrationFiles.sort((a, b) => a.timestamp - b.timestamp);

    } catch (error) {
      console.error('Error reading migrations directory:', error.message);
      return [];
    }
  }

  /**
   * Log migration files in order
   */
  logMigrations() {
    console.log('\n=== Database Migration Script ===');
    console.log('Reading migration files from:', this.migrationsDir);
    console.log('\nMigrations that would be applied (in order):\n');

    const migrationFiles = this.getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No migration files found.');
      console.log('\nExpected format: YYYYMMDDHHMMSS_migration_name.sql');
      console.log('Example: 20240115120000_create_users_table.sql');
      return;
    }

    // Log each migration file
    migrationFiles.forEach((migration, index) => {
      console.log(`${index + 1}. ${migration.name}`);
      console.log(`   Path: ${migration.path}`);
      console.log(`   Timestamp: ${migration.timestamp}`);
      console.log(`   Created: ${migration.createdAt.toLocaleString()}`);
      console.log('');
    });

    console.log(`Total migrations: ${migrationFiles.length}`);
  }

  /**
   * Run the migration script
   */
  run() {
    this.logMigrations();
  }
}

// Create and run the migration runner
const runner = new MigrationRunner();
runner.run();

module.exports = MigrationRunner;

