function readMigrations() {
    const migrationsDir = './migrations/';

    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
        console.log('Migrations directory not found. Creating empty directory.');
        fs.mkdirSync(migrationsDir, { recursive: true });
        return [];
    }

    // Read all files in migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter for SQL files and sort them
    const sqlFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort() // Natural sort will work for timestamp-based filenames
        .map(file => path.join(migrationsDir, file));

    return sqlFiles;
}

function logMigrations(migrations) {
    if (migrations.length === 0) {
        console.log('No migration files found in ./migrations/ directory.');
        return;
    }

    console.log(`Found ${migrations.length} migration file(s):`);
    console.log('Migration files to be applied in order:');

    migrations.forEach((filePath, index) => {
        const filename = path.basename(filePath);
        console.log(`${index + 1}. ${filename}`);
    });
}

