    if (!fs.existsSync(envFilePath)) {
        console.warn(`Warning: ${envFilePath} not found`);
        return null;
    }

    // Read and parse .env.test file
    const envContent = fs.readFileSync(envFilePath, 'utf8');
    const envLines = envContent.split('\n');

    let dbUrl = null;
    for (const line of envLines) {
        if (line.startsWith('DATABASE_URL=')) {
            dbUrl = line.substring('DATABASE_URL='.length).trim();
            // Remove quotes if present
            if (dbUrl.startsWith('"') && dbUrl.endsWith('"')) {
                dbUrl = dbUrl.substring(1, dbUrl.length - 1);
            }
            break;
        }
    }

    if (!dbUrl) {
        console.warn('Warning: DATABASE_URL not found in .env.test');
        return null;
    }

    // Basic validation and masking of sensitive parts
    const maskedUrl = dbUrl.replace(/:([^:@]+)@/, ':****@');
    console.log(`Using database connection: ${maskedUrl}`);

    return dbUrl;
}

