#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const MIGRATIONS_DIR = './migrations/';

function readMigrations() {
    try {
        // Check if migrations directory exists
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.log(`❌ Migrations directory '${MIGRATIONS_DIR}' not found`);
            console.log('📁 Creating migrations directory...');
            fs.mkdirSync(MIGRATIONS_DIR, { recursive: true });
            console.log('✅ Migrations directory created');
            console.log('💡 Add your SQL migration files to the ./migrations/ directory');
            return [];
        }

        // Read directory contents
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for SQL files and sort them
        const sqlFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort((a, b) => {
                // Try to extract numbers for natural sorting (e.g., 001_initial.sql, 002_add_users.sql)
                const numA = parseInt(a.split('_')[0]) || 0;
                const numB = parseInt(b.split('_')[0]) || 0;
                return numA - numB;
            });

        if (sqlFiles.length === 0) {
            console.log('📝 No SQL migration files found in migrations directory');
            console.log('💡 Add .sql files to ./migrations/ directory');
        }

        return sqlFiles;
    } catch (error) {
        console.error('❌ Error reading migrations directory:', error.message);
        return [];
    }
}

function logMigrations(migrations) {
    console.log('🚀 Database Migration Script');
    console.log('='.repeat(50));
    console.log(`📁 Reading migrations from: ${MIGRATIONS_DIR}`);
    console.log('');

    if (migrations.length === 0) {
        console.log('📝 No migrations to apply');
        return;
    }

    console.log('📋 Migrations to apply (in order):');
    console.log('');

    migrations.forEach((file, index) => {
        const filePath = path.join(MIGRATIONS_DIR, file);
        const fileStats = fs.statSync(filePath);
        const fileSize = (fileStats.size / 1024).toFixed(2); // KB

        console.log(`${index + 1}. ${file} (${fileSize} KB)`);
    });

    console.log('');
    console.log(`✅ Total migrations: ${migrations.length}`);
}

function main() {
    console.clear();
    const migrations = readMigrations();
    logMigrations(migrations);
}

// Run the script
main();

-- Add comments table
CREATE TABLE comments (
    id SERIAL PRIMARY KEY,
    post_id INTEGER REFERENCES posts(id),
    user_id INTEGER REFERENCES users(id),
    content TEXT NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Add index for better performance
CREATE INDEX idx_comments_post_id ON comments(post_id);
CREATE INDEX idx_comments_user_id ON comments(user_id);

-- Add user profiles table
CREATE TABLE user_profiles (
    user_id INTEGER PRIMARY KEY REFERENCES users(id),
    first_name VARCHAR(50),
    last_name VARCHAR(50),
    bio TEXT,
    avatar_url VARCHAR(255),
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Add trigger to update updated_at timestamp
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ language 'plpgsql';

CREATE TRIGGER update_user_profiles_updated_at 
    BEFORE UPDATE ON user_profiles 
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

