const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

function readMigrations() {
    const migrationsDir = path.join(__dirname, 'migrations');

    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
        console.log('❌ Migrations directory not found:', migrationsDir);
        console.log('📁 Please create a ./migrations/ directory with your SQL files');
        return;
    }

    // Read all files in migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter for SQL files and sort them
    const sqlFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort((a, b) => {
            // Sort by filename (natural sort for numbered migrations)
            return a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' });
        });

    if (sqlFiles.length === 0) {
        console.log('ℹ️  No SQL migration files found in:', migrationsDir);
        console.log('📝 Expected format: *.sql (e.g., 001_initial_setup.sql, 002_add_users.sql)');
        return;
    }

    console.log('🚀 Migration script would apply the following SQL files in order:');
    console.log('==============================================================');

    // Log each migration file
    sqlFiles.forEach((file, index) => {
        const filePath = path.join(migrationsDir, file);
        const stats = fs.statSync(filePath);

        console.log(`${index + 1}. ${file}`);
        console.log(`   📏 Size: ${(stats.size / 1024).toFixed(2)} KB`);
        console.log(`   📍 Path: ${filePath}`);
        console.log('---');
    });

    console.log(`📊 Total migrations to apply: ${sqlFiles.length}`);
    console.log('==============================================================');
    console.log('ℹ️  This is a dry run. No actual database changes were made.');
    console.log('💡 To actually apply migrations, you would need to:');
    console.log('   1. Connect to your database');
    console.log('   2. Read and execute each SQL file');
    console.log('   3. Track which migrations have been applied');
}

// Handle command line arguments
if (process.argv.includes('--help') || process.argv.includes('-h')) {
    console.log('📋 Migration Script Usage:');
    console.log('   node migrate.js          - List migrations in order');
    console.log('   node migrate.js --help   - Show this help');
    console.log('');
    console.log('📁 Expected directory structure:');
    console.log('   ./migrations/');
    console.log('   ├── 001_initial_setup.sql');
    console.log('   ├── 002_add_users_table.sql');
    console.log('   └── ...');
} else {
    readMigrations();
}

-- Initial database setup
CREATE TABLE IF NOT EXISTS migrations (
    id SERIAL PRIMARY KEY,
    filename VARCHAR(255) NOT NULL UNIQUE,
    applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE users (
    id SERIAL PRIMARY KEY,
    username VARCHAR(50) NOT NULL UNIQUE,
    email VARCHAR(100) NOT NULL UNIQUE,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Add posts table
CREATE TABLE posts (
    id SERIAL PRIMARY KEY,
    user_id INTEGER REFERENCES users(id),
    title VARCHAR(200) NOT NULL,
    content TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_posts_user_id ON posts(user_id);
CREATE INDEX idx_posts_created_at ON posts(created_at);

-- Add comments table
CREATE TABLE comments (
    id SERIAL PRIMARY KEY,
    post_id INTEGER REFERENCES posts(id),
    user_id INTEGER REFERENCES users(id),
    content TEXT NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_comments_post_id ON comments(post_id);
CREATE INDEX idx_comments_user_id ON comments(user_id);

-- Add comment_count to posts table
